24.     document.removeEventListener("visibilitychange", retryWhenDocumentBecomesVisible);
25. 
26.     try {
27.         // Reconnect will asynchronously return:
28.         // - true to mean success
29.         // - false to mean we reached the server, but it rejected the connection (e.g., unknown circuit ID)
30.         // - exception to mean we didn't reach the server (this can be sync or async)
31.         const successful = await Blazor.reconnect();
32.         if (!successful) {
33.             // We have been able to reach the server, but the circuit is no longer available.
34.             // We'll reload the page so the user can continue using the app as quickly as possible.
35.             const resumeSuccessful = await Blazor.resumeCircuit();
36.             if (!resumeSuccessful) {
